"""The circular cylinder at Re 100 (docs/validation/cylinder_re100/SETUP.md): the section generated by code and the
app project set up for it (2D mode, laminar, transient). No Qt.

The cylinder is imported as a 2D section (a closed circle of diameter D = 1 m written as a Selig file, the app's
airfoil import, D-121), so the app meshes it in its 2D mode. Re = U D / nu = 100 with U = 1 m/s and nu = 0.01 m2/s:
the flow-through time of the diameter, t_c = D / U, is 1 s.
"""

import math
from pathlib import Path

import numpy as np

DIAMETER = 1.0
SPEED = 1.0
NU = 0.01  # Re = 100
RE = SPEED * DIAMETER / NU

# The domain (SETUP.md, "Domain"): the "2D airfoil" C-type far field, its radius and wake in diameters. A radius of
# 30 D puts the far field 30 D ahead and to each side: a blockage D / H of 1/60 = 1.7 %.
RADIUS = 30.0
WAKE = 50.0

# The mesh levels (SETUP.md, "Mesh study"): the background cell (m) of each level; the surface and the wake box keep
# their refinement levels, so every cell scales with the background cell (refinement ratio sqrt(2)).
LEVELS = {"coarse": math.sqrt(2.0), "medium": 1.0, "fine": 1.0 / math.sqrt(2.0)}
SURFACE_LEVEL = 7  # the surface cell: base / 128
WAKE_LEVEL_SIZE = 1.0 / 16.0  # the wake box's target size per metre of background cell; scaled with the level
WAKE_BOX = ((8.0, 0.0, 0.0), (17.0, 1.0, 5.0))  # centre and size (x 0.5 D ahead of the centre to 16.5 D behind)
LAYERS = 4  # relative prism layers (the laminar boundary layer, about D / sqrt(Re) = 0.1 D thick)

# The run (SETUP.md, "Run"): adaptive at Co 1 (the app's default), the start-up detected over windows of 20 t_c,
# and the end time.
END_TIME = 180.0  # t_c
WINDOW = 20.0  # t_c
CORES = 4

# The references (SETUP.md, "References") and the pass rule (written before the runs).
# Sourced (Part 0 of task 1.1-transient, SETUP.md "References"): Constant et al. (2016, arXiv:1609.04364) Table 3 and
# Dong & Shen (2014, arXiv:1409.6676) Table 2. The tolerances below are the rule as first written.
ST_BAND = (0.164, 0.165)  # Williamson (1996), Norberg (1994): 0.164; Barkley & Henderson (1996): 0.165
ST_TOLERANCE = 0.03
CD_REFERENCE = 1.35  # mean Cd: Henderson (1995) 1.35; Blackburn & Henderson (1999) 1.35
CD_TOLERANCE = 0.05
CL_RMS_REFERENCE = 0.253  # RMS of Cl: Dong & Shen (2014), wake 15 D and 20 D (literature spread there 0.21-0.27)
CL_RMS_TOLERANCE = 0.15


def circle_selig(points: int = 721) -> str:
    """A circle of diameter D in the Selig order (from x = D, y = 0 over the upper half to x = 0 and back along the
    lower half), centred on (D/2, 0)."""
    theta = np.linspace(0.0, 2.0 * math.pi, points)
    x = 0.5 * DIAMETER * (1.0 + np.cos(theta))
    y = 0.5 * DIAMETER * np.sin(theta)
    rows = [f"{xi:.10f} {yi:.10f}" for xi, yi in zip(x, y)]
    return "Circular cylinder D = 1 (Selig order)\n" + "\n".join(rows) + "\n"


def write_dat(path: Path) -> Path:
    Path(path).write_text(circle_selig(), encoding="utf-8")
    return Path(path)


def reference_st() -> float:
    return 0.5 * (ST_BAND[0] + ST_BAND[1])


def verdict(st: float | None, cd_mean: float | None, cl_rms: float | None) -> tuple[str, dict]:
    """(PASS / FAIL, the errors): St within 3 % of the band (0 inside it), mean Cd within 5 % of 1.35, the RMS of Cl
    within 15 % of 0.253."""
    def band_error(value: float) -> float:
        lo, hi = ST_BAND
        if lo <= value <= hi:
            return 0.0
        return (value - hi) / hi if value > hi else (value - lo) / lo

    if st is None or cd_mean is None or cl_rms is None:
        return "FAIL", {}
    errors = {"st": band_error(st), "cd": (cd_mean - CD_REFERENCE) / CD_REFERENCE,
              "cl_rms": (cl_rms - CL_RMS_REFERENCE) / CL_RMS_REFERENCE}
    ok = (abs(errors["st"]) <= ST_TOLERANCE and abs(errors["cd"]) <= CD_TOLERANCE
          and abs(errors["cl_rms"]) <= CL_RMS_TOLERANCE)
    return ("PASS" if ok else "FAIL"), errors


def build_project(folder: Path, level: str = "coarse", end_time: float = END_TIME, cores: int = CORES,
                  window: float = WINDOW, sampling_start: float | None = None, write_interval: float | None = None,
                  **transient_settings):
    """The project in ``folder`` (created): the "2D airfoil" preset, laminar transient flow at Re 100, the cylinder
    imported as a section, the domain, the level's mesh and the wake box; ``transient_settings``: more Transient
    fields (Part 2: the PIMPLE and perturbation runs). The study of Part 1 ran without the start-up perturbation
    (it did not exist), so it is off unless set. Returns the Project."""
    from vortexcfd.core.model import BoxShape, RefinementVolume
    from vortexcfd.core.presets import BUILTIN_PRESETS, apply_preset
    from vortexcfd.core.project import Project
    from vortexcfd.workflow import part_ops

    base = LEVELS[level]
    folder = Path(folder)
    (folder / "geometry").mkdir(parents=True, exist_ok=True)
    project = Project.new(f"cylinder_{level}")
    project._sim = apply_preset(project.sim, next(p for p in BUILTIN_PRESETS if p.name == "2D airfoil"))
    project.update_physics(nu=NU, flow="incompressible_transient", turbulence_model="laminar")
    project.update_inflow(speed=SPEED)
    project.update_reports(reference_length=DIAMETER, center_of_rotation=(0.5 * DIAMETER, 0.0, 0.0))
    project.update_domain(radius=RADIUS, downstream=WAKE)
    project.update_mesh(base_size=base, surface_level_min=SURFACE_LEVEL, surface_level_max=SURFACE_LEVEL,
                        layer_sizing="relative", layer_controls="robust", layers=LAYERS)
    project.update_solver(cores=cores, live_view=False)
    project.update_transient(end_time=end_time, write_interval=write_interval or end_time, window=window,
                             sampling_start=sampling_start, **{"perturb": False, **transient_settings})
    centre, size = WAKE_BOX
    project._sim = project.sim.model_copy(update={"refinement_volumes": [RefinementVolume(
        id="wake", name="Wake", shape=BoxShape(centre=centre, size=size), target_size=WAKE_LEVEL_SIZE * base,
        frame="wind")]})
    project.save(folder / "cylinder.json")
    dat = write_dat(folder / "cylinder.dat")
    project.add_part(part_ops.airfoil_part(folder, dat, "cylinder", set(), closure="sharp"))
    project.save()
    return project
